export const html = "<p class=\"lead\">بیست اشتباه رایج (از <code>add .</code> کور تا force روی <code>main</code>) و برای هر کدام همان Undo مشخص. قبل از کپی فرمان، ستون «چه‌کار نکن» را بخوان.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>اشتباه را نام ببری قبل از اینکه فاجعه شود</li>\n<li>راه‌حل درست را از راه‌حل خطرناک جدا کنی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">💣 لیست</span></span></h2>\n<ol>\n<li><strong><code>git add .</code> کور:</strong> <code>.env</code> و <code>dist</code> می‌آید. راه‌حل: <code>-p</code> و gitignore.</li>\n<li><strong>کامیت روی main:</strong> Ruleset + <code>branchProtection</code> در VS Code.</li>\n<li><strong>پیام <code>update</code>:</strong> Conventional.</li>\n<li><strong>amend بعد از push:</strong> revert یا کامیت جدید.</li>\n<li><strong><code>--force</code> به origin/main:</strong> lease + ممنوعیت سرور.</li>\n<li><strong>rebase شاخهٔ مشترک:</strong> merge یا revert.</li>\n<li><strong>Discard در VS Code بدون Timeline:</strong> Local History را فوراً چک کن.</li>\n<li><strong>clone با HTTPS و بعداً گیر token:</strong> remote را به SSH عوض کن.</li>\n<li><strong>ignore کردن فایل trackشده:</strong> <code>rm --cached</code>.</li>\n<li><strong>حل تعارض با Accept Both کور:</strong> تست.</li>\n<li><strong>PR ۵۰۰۰ خطی:</strong> بشکن.</li>\n<li><strong>Approve بدون اجرای کد:</strong> حداقل تست CI اجباری.</li>\n<li><strong>secret در پیام کامیت:</strong> revoke.</li>\n<li><strong>submodule فراموش‌شده:</strong> <code>clone --recurse-submodules</code> (اگر تیم submodule دارد؛ وگرنه اجتناب).</li>\n<li><strong>نام شاخه با فاصله:</strong> از <code>/</code> و <code>-</code>.</li>\n<li><strong>کشیدن ZIP به‌جای clone:</strong> تاریخچه نداری.</li>\n<li><strong>دو نفر یک worktree/شاخه:</strong> قفل Git.</li>\n<li><strong>اعتماد به Smart Commit:</strong> خاموشش کن.</li>\n<li><strong>اکشن <code>@main</code>:</strong> pin.</li>\n<li class=\"keep-next\"><strong>فکر کردن که GitHub = بکاپ تنها:</strong> remote دوم یا mirror برای چیزهای حیاتی.</li>\n</ol>\n<div class=\"cols\">\n<div class=\"col bad\"><div class=\"col-title\">«الان force می‌زنم بعداً درست می‌کنم»</div>\n<p>تاریخچهٔ دیگران را نمی‌توانی بعداً آسان درست کنی.</p>\n</div>\n<div class=\"col good\"><div class=\"col-title\">«lease، بعد در PR توضیح»</div>\n<p>شفافیت &gt; سرعت جعلی.</p>\n</div>\n</div>\n<div class=\"diagram\">\n<img src=\"/book/figures/undo-map.svg\" alt=\"یادآوری Undo\"/>\n<p class=\"figcap\">شکل ۱۹ — قبل از هر فرمان مخرب، این نقشه را ببین.</p>\n</div>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>سؤال محبوب:</strong> «بدترین اشتباه Git تو چه بود؟» صادق باش + بگو از کدام ابزار (reflog، revert، Ruleset) بعدش استفاده کردی. رشد را نشان می‌دهد.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ جمع‌بندی</span></span></h2>\n<p>اشتباه نکردن هدف نیست؛ اشتباه غیرقابل‌برگشت نکردن هست. Git برای برگشت ساخته شده مگر force روی عمومی.</p>\n<p><strong>فصل بعد:</strong> مصاحبه، واژه‌نامه و نقشه راه.</p>";
